package config_test

import (
	"mc_manager/config"
	"testing"
	_ "unsafe"

	"github.com/stretchr/testify/assert"
)

func TestImageValidation(t *testing.T) {
	// Test valid image
	validImageString := "data:image/png;base64,"
	err := config.ValidateImage(&validImageString)
	assert.NoError(t, err)

	invalidImageString := "invalid_image_string"
	err = config.ValidateImage(&invalidImageString)
	assert.Error(t, err)
	assert.Contains(t, err.Error(), "illegal base64 data")

	largeImageString := ``
	err = config.ValidateImage(&largeImageString)
	assert.Error(t, err)
	assert.Equal(t, "image dimensions are not 64x64", err.Error())

	// Test with nil image
	err = config.ValidateImage(nil)
	assert.Error(t, err)
	assert.Equal(t, "base64 image is nil", err.Error())

	// Test jpeg image
	jpegImageString := "data:image/jpeg;base64,"
	err = config.ValidateImage(&jpegImageString)
	assert.Error(t, err)
	assert.Equal(t, "image: unknown format", err.Error())
}
